def counting_sort_by_digit(a, exp):
    n = len(a)
    output = [0] * n
    count = [0] * 10
    for x in a:
        count[(x // exp) % 10] += 1
    for i in range(1, 10):
        count[i] += count[i - 1]
    for i in range(n - 1, -1, -1):
        digit = (a[i] // exp) % 10
        count[digit] -= 1
        output[count[digit]] = a[i]
    a[:] = output


def radix_sort(a):
    if not a:
        return a
    max_val = max(a)
    exp = 1
    while max_val // exp > 0:
        counting_sort_by_digit(a, exp)
        exp *= 10
    return a


